  function seasonCard(s) { const imgs = { spring: 'https://lll.ba/wp-content/uploads/2023/04/Pliva-Waterfall-Plivski-vodopad-Jajce-Bosnia-Herzegovina-lll.ba-%40sandronuhanovic-2.jpg', summer: 'https://www.belmondo-cruises.com/upld/xl/1464/mostar-dalmatian-coast-cruises-croatia.webp', autumn: 'https://ditisbosnie.nl/wp-content/uploads/2018/04/Sarajevo-Sebilj-en-Bas%CC%8Cc%CC%8Cars%CC%8Cija-1024x768.jpg', winter: 'https://vlasicki-konak.com/wp-content/uploads/2018/05/49402-1.jpg' }; const ss = SEASON[s]; return `<button class="season-card ${season() === s ? 'selected' : ''}" style="background-image:url('${imgs[s]}')" data-season-choice="${s}" aria-label="${esc(v(ss[0], ss[1]))}"><div><span class="season-title">${ss[2]} ${v(ss[0], ss[1])}</span><p>${v(ss[3], ss[4])}</p><span class="season-arrow">${icon('arrow')}</span></div></button>`; }
