 <section class="section" style="padding-top:0"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">${v('FESTIVALI I DOŽIVLJAJI', 'EVENTS & EXPERIENCES')}</span><h2 class="section-title">${v('Ne propusti ono posebno.', 'Don’t miss the extraordinary.')}</h2><p class="section-desc">${v('Travnička noćna utrka, skokovi sa Starog mosta, Sarajevo Film Festival i još mnogo toga.', 'Travnik Night Run, Mostar cliff diving, Sarajevo Film Festival and more.')}</p></div><button class="text-link" data-view="events">${v('Svi događaji', 'All events')} ${icon('arrow')}</button></div></div></section>
